async function POSTKEYPHP(params = {}) {
    try {
        
        const IV = 生成随机IV();
        const encryptedData = APP_encryptRequestParams(params, IV, 'key');

        
        if (!当前选中的应用ID) {
            return {
                success: false,
                message: '应用ID不能为空'
            };
        }
        
        const requestBody = JSON.stringify({
            developer_username: 开发者UID,
            iv: IV,
            app_id: 当前选中的应用ID,
            data: encryptedData
        });

        const response = await fetch(获取API链接('key.php'), {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json; charset=utf-8',
            },
            body: requestBody
        });
        
        const responseText = await response.text();
        
    
        try {
            const jsonResult = JSON.parse(responseText);
            return jsonResult;
        } catch (e) {
        }
        
        let decryptedData;
        try {
            decryptedData = APP_解密(responseText, IV);
            
        } catch (decryptError) {
            return {
                success: false,
                message: responseText
            };
        }
        
        let result;
        try {
            result = JSON.parse(decryptedData);
        } catch (parseError) {
            try {
                const cleanedData = decryptedData.trim();
                result = JSON.parse(cleanedData);
            } catch (cleanError) {
                return {
                    success: false,
                    message: responseText
                };
            }
        }
        
        
        if(!APP_校验响应签名(result)){
        return {
            success: false,
            message: '返回响应不可信,请检查签名状态'
        };
        }
        
        return result;
        
    } catch (error) {
        return {
            success: false,
            message: '网络请求失败: ' + error.message
        };
    }
}


