function 卡密管理_全选所有(checkbox) {
    const checkboxes = document.querySelectorAll('.卡密管理-选择按钮:not(:disabled)');
    const isChecked = checkbox.checked;
    
    const 卡密管理_多选功能id = document.getElementById('卡密管理_多选功能id');
    if(isChecked){
    卡密管理_多选功能id.style.display = 'flex';
    }else{
    卡密管理_多选功能id.style.display = 'none';
    }
    卡密管理_选中的.clear();
    
    checkboxes.forEach(cb => {
        cb.checked = isChecked;
        if (isChecked) {
            卡密管理_选中的.add(cb.value);
        }
    });
    
}



function 卡密管理_选择按钮处理事件(appId, isSelected) {
    if (isSelected) {
        卡密管理_选中的.add(appId);
        
    const 卡密管理_多选功能id = document.getElementById('卡密管理_多选功能id');
    卡密管理_多选功能id.style.display = 'flex';
    } else {
        卡密管理_选中的.delete(appId);
        
    if (卡密管理_选中的.size === 0) {
        
    const 卡密管理_多选功能id = document.getElementById('卡密管理_多选功能id');
    卡密管理_多选功能id.style.display = 'none';
    }
    }
    
    const allCheckboxes = document.querySelectorAll('.卡密管理-选择按钮');
    const checkedCheckboxes = document.querySelectorAll('.卡密管理-选择按钮:checked');
    const selectAllCheckbox = document.getElementById('卡密管理_选择所有_id');
    
    if (selectAllCheckbox) {
        if (allCheckboxes.length > 0 && checkedCheckboxes.length === 卡密管理_当前页数量) {
            selectAllCheckbox.checked = true;
        } else {
            selectAllCheckbox.checked = false;
        }
    }
}






