async function 卡密管理_选中功能_导出() {
    try {
        const 选中的格式化 = Array.from(卡密管理_选中的).join('\n');
        const blob = new Blob([选中的格式化], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        
        const 当前时间 = new Date();
        const 时间字符串 = 当前时间.toISOString()
            .replace(/T/, '_')
            .replace(/\..+/, '')
            .replace(/:/g, '-');
        
        a.download = `卡密导出_${时间字符串}.txt`;
        a.click();
        URL.revokeObjectURL(url);
    } catch (error) {
        alert('导出失败');
    }
}

