function formatDateTime(timestamp) {
    if (!timestamp) return '';
    
    if (typeof timestamp === 'string' && timestamp.includes('-')) {
        return timestamp;
    }
    
    try {
        const date = new Date(timestamp);
        if (isNaN(date.getTime())) {
            return timestamp;
        }
        
        return date.toLocaleString('zh-CN', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit'
        }).replace(/\//g, '-');
    } catch (e) {
        return timestamp;
    }
}


async function createCards() {
    const createCardBtn = document.getElementById('createCardBtn');
    if (!createCardBtn) {
        alert('无法找到生成按钮', false);
        return;
    }
    
    const originalBtnText = createCardBtn.innerHTML;
    
    try {
        createCardBtn.disabled = true;
        createCardBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 正在生成...';
        
        let generatedCards = [];
        let cleanAppName = '';
        let durationDays = 0;
        let durationHours = 0;
        let durationMinutes = 0;
        let cardCount = 0;
        
        const cardType = parseInt(document.getElementById('cardType')?.value);
        const 创建卡密_卡密格式 = document.getElementById('创建卡密_卡密格式')?.value || '1';
        const 创建卡密_令牌长度 = document.getElementById('创建卡密_令牌长度')?.value || '8';
        const durationDaysInput = parseInt(document.getElementById('durationDays')?.value) || 0;
        const durationHoursInput = parseInt(document.getElementById('durationHours')?.value) || 0;
        const durationMinutesInput = parseInt(document.getElementById('durationMinutes')?.value) || 0;
        
        const maxDevices = document.getElementById('maxDevices')?.value || '1';
        const activationCount = document.getElementById('activationCount')?.value || '1';
        const cardCreator = 开发者UID;
        const cardNotes = document.getElementById('cardNotes')?.value || '';

        if (durationDaysInput < 0 || durationHoursInput < 0) {
            alert('有效天数与有效小时不能为负数', false);
            createCardBtn.disabled = false;
            createCardBtn.innerHTML = originalBtnText;
            return;
        }

        if (durationDaysInput > 36500) {
            alert('有效天数上限36500天', false);
            createCardBtn.disabled = false;
            createCardBtn.innerHTML = originalBtnText;
            return;
        }

        if (durationHoursInput > 999) {
            alert('有效小时上限999小时', false);
            createCardBtn.disabled = false;
            createCardBtn.innerHTML = originalBtnText;
            return;
        }

        if (durationMinutesInput > 99999) {
            alert('有效分钟上限99999分钟', false);
            createCardBtn.disabled = false;
            createCardBtn.innerHTML = originalBtnText;
            return;
        }

        durationDays = durationDaysInput;
        durationHours = durationHoursInput;
        durationMinutes = durationMinutesInput;

        let cardKeysInput = '';
        if (创建卡密类型 === 'batch') {
            const appNameInput = document.getElementById('appName');
            const cardCountInput = document.getElementById('cardCount');
            
            const appName = appNameInput?.value || '';
            cardCount = parseInt(cardCountInput?.value || '1');
            
            if (!appName) {
                alert('请输入卡密前缀', false);
                createCardBtn.disabled = false;
                createCardBtn.innerHTML = originalBtnText;
                return;
            }
            
            if (!cardCount || cardCount <= 0 || cardCount > 500) {
                alert('请输入正确的生成数量（1-500）', false);
                createCardBtn.disabled = false;
                createCardBtn.innerHTML = originalBtnText;
                return;
            }

            cleanAppName = appName
                .replace(/[^a-zA-Z0-9\u4e00-\u9fa5]/g, '')
                .substring(0, 15);
            
            if (!cleanAppName) {
                alert('卡密前缀无效，请使用字母、数字或中文', false);
                createCardBtn.disabled = false;
                createCardBtn.innerHTML = originalBtnText;
                return;
            }
            
            function formatUuid(token) {
                // 令牌只含 A-Z0-9，转成合法 hex 片段：A-Z -> 0-9a-f 的稳定映射
                const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
                const hexes = '0123456789abcdef';
                let h = '';
                for (let i = 0; i < 32; i++) {
                    const c = token.charAt(i % Math.max(1, token.length));
                    const pos = chars.indexOf(c);
                    h += hexes.charAt(pos >= 0 ? pos % 16 : (i % 16));
                }
                // RFC4122 v4 形态：版本位 4，变体位 a
                return `${h.slice(0,8)}-${h.slice(8,12)}-4${h.slice(13,16)}-a${h.slice(17,20)}-${h.slice(20,32)}`;
            }

            function generateRandomString(length = 8) {
                const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
                let result = '';
                const charsLength = chars.length;
                for (let i = 0; i < length; i++) {
                    result += chars.charAt(Math.floor(Math.random() * charsLength));
                }
                return result;
            }
            
            // 生成时长片段（多种风格复用）
            function buildDurationTokens() {
                const isForever = (durationDays == 36500);
                let compact = '';
                if (isForever) {
                    compact = '永久';
                } else {
                    if (durationDays > 0) compact += `${durationDays}D`;
                    if (durationHours > 0) compact += `${durationHours}H`;
                    if (durationMinutes > 0) compact += `${durationMinutes}M`;
                    if (compact === '') compact = '永久';
                }
                // 中文风格
                let cn = '';
                if (isForever) {
                    cn = '永久';
                } else {
                    if (durationDays > 0) cn += `${durationDays}天`;
                    if (durationHours > 0) cn += `${durationHours}小时`;
                    if (durationMinutes > 0) cn += `${durationMinutes}分钟`;
                    if (cn === '') cn = '永久';
                }
                return { compact, cn, isForever };
            }

            const tokens = buildDurationTokens();

            // 按请求数量做全局去重（上限 200 次重试/张）
            const seen = new Set(generatedCards);
            for (let i = 0; i < cardCount; i++) {
                let cardKey = '';
                let guard = 0;
                do {
                    const randomPart = generateRandomString(创建卡密_令牌长度);
                    const uuidPart = formatUuid(generateRandomString(32));
                    const numPart = String(Math.floor(Math.random() * 9e9) + 1e9);
                    const groupPart = generateRandomString(4) + '-' + generateRandomString(4) + '-' + generateRandomString(4);

                    switch (String(创建卡密_卡密格式)) {
                        case '1': // JiYan-前缀-时长-令牌
                            cardKey = `JiYan-${cleanAppName}-${tokens.compact}-${randomPart}`;
                            break;
                        case '2': // 仅令牌
                            cardKey = randomPart;
                            break;
                        case '3': // 前缀-时长-令牌（无 JiYan）
                            cardKey = `${cleanAppName}-${tokens.compact}-${randomPart}`;
                            break;
                        case '4': // JiYan_前缀_时长_令牌（下划线）
                            cardKey = `JiYan_${cleanAppName}_${tokens.compact}_${randomPart}`;
                            break;
                        case '5': // JiYan-前缀-中文时长-令牌
                            cardKey = `JiYan-${cleanAppName}-${tokens.cn}-${randomPart}`;
                            break;
                        case '6': // 分组卡密 XXXX-XXXX-XXXX
                            cardKey = groupPart;
                            break;
                        case '7': // UUID 风格
                            cardKey = uuidPart;
                            break;
                        case '8': // 纯数字卡密
                            cardKey = numPart;
                            break;
                        default:
                            cardKey = `JiYan-${cleanAppName}-${tokens.compact}-${randomPart}`;
                    }
                    guard++;
                } while (seen.has(cardKey) && guard < 200);

                seen.add(cardKey);
                generatedCards.push(cardKey);
            }
            
            cardKeysInput = generatedCards.join(' ');
            
        } else if (创建卡密类型 === 'custom') {
            const cardKeysInputElement = document.getElementById('cardKeysInput');
            if (!cardKeysInputElement) {
                alert('无法找到自定义卡密输入框', false);
                createCardBtn.disabled = false;
                createCardBtn.innerHTML = originalBtnText;
                return;
            }
            
            cardKeysInput = cardKeysInputElement.value.trim();

            if (!cardKeysInput) {
                alert('请输入卡密号码', false);
                createCardBtn.disabled = false;
                createCardBtn.innerHTML = originalBtnText;
                return;
            }
            
            const customCards = cardKeysInput.split(/\s+/).filter(key => key.length > 0);
            generatedCards = customCards;
            cardCount = generatedCards.length;
            
            if (cardCount === 0) {
                alert('请输入有效的卡密号码', false);
                createCardBtn.disabled = false;
                createCardBtn.innerHTML = originalBtnText;
                return;
            }
            
            for (const card of generatedCards) {
                if (card.length > 50) {
                    alert(`卡密号码过长：${card}，最大长度50字符`, false);
                    createCardBtn.disabled = false;
                    createCardBtn.innerHTML = originalBtnText;
                    return;
                }
            }
        }
        
        if (!cardKeysInput || cardKeysInput.trim() === '') {
            alert('卡密号码不能为空，请检查输入', false);
            createCardBtn.disabled = false;
            createCardBtn.innerHTML = originalBtnText;
            return;
        }
        
        let estimatedPrice = 0;
        if (会员状态.includes('会员有效')) {
            estimatedPrice = cardCount * 0.03;
        } else {
            estimatedPrice = cardCount * 0.05;
        }
        
        if (!confirm(`确定要创建${cardCount}张卡密吗？`)) {
            alert('操作被取消');
            createCardBtn.disabled = false;
            createCardBtn.innerHTML = originalBtnText;
            return;
        }
        
        const params = {
            action: 'create_card',
            password: 开发者安全密码,
            card_keys: cardKeysInput,
            card_type: cardType,
            duration_days: durationDays,
            duration_hours: durationHours,
            duration_minutes: durationMinutes
        };
        
        if (cardType === Env卡密类型.设备卡密) {
            params.max_devices = parseInt(maxDevices);
        }
        
        if (cardCreator) {
            params.creator = cardCreator;
        }
        if (cardNotes) {
            params.notes = cardNotes;
        }
        
        const result = await POSTKEYPHP(params);
        
        if (result.success) {
            alert(result.message, true);
            
            let 创建成功的卡密 = result.data;
            let 卡密数组 = Object.keys(创建成功的卡密)
                .filter(key => !isNaN(parseInt(key)))
                .map(key => 创建成功的卡密[key]);

            await exportCardsToTxt(卡密数组);
            
            关闭创建卡密弹窗();
            
            setTimeout(() => {
                加载卡密数据(卡密管理_当前页码);
            }, 500);
        } else {
            alert('创建卡密失败: ' + result.message, false);
        }
        
    } catch (error) {
        alert('创建卡密时发生错误: ' + error.message, false);
    } finally {
        if (createCardBtn) {
            createCardBtn.disabled = false;
            createCardBtn.innerHTML = originalBtnText;
        }
    }
}

async function exportCardsToTxt(cards) {
    try {
        if (!cards || cards.length === 0) {
            return;
        }
        
        const now = new Date();
        const timestamp = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}_${String(now.getHours()).padStart(2, '0')}${String(now.getMinutes()).padStart(2, '0')}${String(now.getSeconds()).padStart(2, '0')}`;
        const filename = `卡密_${timestamp}.txt`;
        
        const fileContent = cards.join('\n');
        const blob = new Blob([fileContent], { type: 'text/plain;charset=utf-8' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = filename;
        
        document.body.appendChild(link);
        link.click();
        
        setTimeout(() => {
            document.body.removeChild(link);
            URL.revokeObjectURL(link.href);
        }, 100);
    } catch (error) {
    }
}

